-- ============================================================================
-- Siembra del banco combustible_evaluacion (40 preguntas).
--
-- ARCHIVO GENERADO: no se edita a mano. El banco se edita en
-- contenido/bancos/combustible_evaluacion.json, y esto es la salida de
--   node scripts/bancos/sembrar.mjs combustible_evaluacion
-- con esta cabecera encima. Si el JSON cambió después de la fecha de abajo,
-- se pega la salida del comando en vez de este archivo.
--
-- Generado el 25-sep-2026. Upsert por id; lo que sale del archivo queda
-- inactivo, nunca borrado. Va DESPUÉS de la migración de RAC y Combustible
-- (el banco no depende de ella, pero la evaluación no abre sin sus reglas).
-- Orden completo: docs/RAC_COMBUSTIBLE_ESTADO.md.
-- ============================================================================
-- Banco combustible_evaluacion: 40 preguntas
with datos as (
  select *
  from jsonb_to_recordset($banco$[{"id":"ev-01","enunciado":"Durante la preparación, el DV te dice que el cálculo del combustible «es asunto del despacho» y que tú solo firmas. Según el RAC 121, ¿cómo se reparte esa responsabilidad?","opciones":["El DV responde por el OFP y el PIC solo por la ejecución del vuelo.","El PIC y el DV responden juntos por el planeamiento previo y la ejecución.","El director de operaciones responde por el combustible y lo delega en el DV.","El PIC solo responde por el discrecional que decide añadir al despacho del vuelo."],"correcta":1,"explicacion":"El PIC y el DV son responsables de manera conjunta del planeamiento previo al vuelo y de su ejecución, según el MO. Por eso revisas el OFP componente por componente y no te limitas a firmar.","referencia":"RAC 121, 121.2215 (c)","metadatos":{"tema":"C01","capitulo":1}},{"id":"ev-02","enunciado":"Tu masa sin combustible es 52.400 kg. El OFP trae block fuel 9.100 kg y rodaje 250 kg. ¿Qué masa de despegue debes usar?","opciones":["61.500 kg","61.750 kg","61.250 kg","61.000 kg"],"correcta":2,"explicacion":"La masa de despegue es la masa sin combustible más el combustible de despegue, que es el block fuel menos el rodaje: 52.400 + 8.850 = 61.250 kg. Usar el block fuel (61.500) es el error de confundir block fuel con combustible de despegue.","referencia":"RAC 121, 121.2645 (c)(1); 121.2835 (a)(1)","metadatos":{"tema":"C02","capitulo":2}},{"id":"ev-03","enunciado":"Si el vuelo sale exactamente como lo planificó el OFP, con el adicional en cero, ¿qué combustible deberías tener al aterrizar en destino?","opciones":["Contingencia, alterno, reserva final y discrecional.","Solo la reserva final, porque lo demás se planifica para consumirse.","Alterno y reserva final, porque la contingencia siempre se consume en ruta.","El block fuel menos el trayecto, porque el rodaje también llega a destino."],"correcta":0,"explicacion":"Al aterrizaje llega el combustible de despegue menos el trayecto: contingencia, alterno y reserva final, que no se planea consumir, más el discrecional. El error típico es restar otra vez el rodaje, que ya se quemó antes del despegue.","referencia":"RAC 121, 121.2645 (c)(1) a (c)(7)","metadatos":{"tema":"C02","capitulo":2}},{"id":"ev-04","enunciado":"Llegas a la espera en destino con 350 kg de discrecional sin usar, 130 kg de contingencia restante y el adicional en cero. El alterno es 1.400 kg y la reserva final 1.300 kg. La espera cuesta 48 kg/min. ¿Cuánto puedes esperar antes de empezar a gastar el combustible del alterno?","opciones":["Unos 7 minutos","Unos 3 minutos","Unos 39 minutos","Unos 10 minutos"],"correcta":3,"explicacion":"Antes del alterno solo están tus márgenes: 350 + 130 = 480 kg, y 480 ÷ 48 = 10 minutos. Con 7 o 3 contarías solo uno de los dos márgenes, y con 39 ya estarías gastando el alterno.","referencia":"RAC 121, 121.2645 (c)(3), (c)(4) y (c)(7); 121.2553 (b)(1)","metadatos":{"tema":"C03","capitulo":3}},{"id":"ev-05","enunciado":"El destino cierra y te desvías a un aeródromo que no era ni tu destino ni tu alterno. Según el RAC 121, ¿con cuánto combustible, como mínimo, debes planear aterrizar allí?","opciones":["Con el alterno más la reserva final, igual que en el despacho.","Con la reserva final prevista: es el mínimo al aterrizar en cualquier aeródromo.","Con 15 minutos de espera, porque ese aeródromo no estaba en el despacho.","Sin mínimo fijo: en un desvío no planificado manda el criterio del PIC."],"correcta":1,"explicacion":"La reserva final prevista es la cantidad mínima con la que se debe aterrizar en cualquier aeródromo, no solo en destino o alterno. Por eso la vigilancia continua se hace contra un aeródromo donde puedas aterrizar con esa reserva intacta.","referencia":"RAC 121, 121.2553 (b) y (b)(3), Nota 1","metadatos":{"tema":"C03","capitulo":3}},{"id":"ev-06","enunciado":"Ayer y hoy, en la misma ruta, el block fuel es 9.200 kg. Hoy cambió el alterno y su combustible pasó de 1.200 a 1.600 kg; los demás componentes obligatorios no cambiaron. ¿Qué pasó con tu discrecional?","opciones":["Subió 400 kg, porque el nuevo alterno exige más combustible.","No cambió, porque el block fuel es el mismo que ayer.","Bajó 400 kg: hoy tienes menos margen propio.","No cambió: los 400 kg salieron de la contingencia."],"correcta":2,"explicacion":"Si el total no cambia y el alterno sube 400 kg, esos 400 kg salen del discrecional. Por eso el OFP se lee componente por componente: el mismo block fuel puede esconder menos margen.","referencia":"RAC 121, 121.2645 (c)(4) y (c)(7)","metadatos":{"tema":"C03","capitulo":3}},{"id":"ev-07","enunciado":"Tu OFP: rodaje 220, trayecto 4.600, contingencias 230, alterno 1.350, reserva final 1.300, adicional 0 y discrecional 250 kg (block 7.950). Por una cola larga consumes 520 kg en rodaje. En cabecera, según el RAC 121, ¿puedes despegar?","opciones":["No: tienes 7.430 kg y el requerido para despegar es 7.480 kg.","No: tienes 7.430 kg y el requerido es el block fuel, 7.950 kg.","Sí: la contingencia puede usarse en el rodaje si el PIC lo acepta.","Sí: tienes 7.430 kg y solo necesitas trayecto y reserva final."],"correcta":0,"explicacion":"El requerido para despegar es trayecto, contingencias, alterno y reserva final: 7.480 kg. Con 7.430 kg no se despega; se regresa a cargar o se replanifica según el MO, y el block fuel no es el mínimo porque incluye rodaje y discrecional.","referencia":"RAC 121, 121.2645 (d)","metadatos":{"tema":"C04","capitulo":4}},{"id":"ev-08","enunciado":"Sales con un ítem de la MEL que, según tu manual, aumenta el consumo un 3 %. El trayecto sin esa penalización es 4.000 kg y la contingencia, 200 kg. Tu compañero propone no tocar el cálculo porque «la contingencia lo cubre». Según el RAC 121, ¿qué le respondes?","opciones":["Que sí: los 120 kg caben en los 200 kg de contingencia, que existe para eso.","Que sí, siempre que el PIC lo acepte y lo deje anotado en el OFP del vuelo.","Que no: un ítem de MEL que aumenta el consumo se cubre con el adicional.","Que no: esos 120 kg son previsibles y van en el cálculo previo."],"correcta":3,"explicacion":"El efecto de los ítems de mantenimiento diferidos es una de las condiciones operacionales en que se basa el cálculo previo: 4.000 × 3 % = 120 kg que se conocen antes de salir. No es un imprevisto para la contingencia ni un caso del adicional, que cubre la falla en el punto crítico.","referencia":"RAC 121, 121.2645 (b)(2)(v), (c)(3), Nota, y (c)(6)","metadatos":{"tema":"C04","capitulo":4}},{"id":"ev-09","enunciado":"El OFP se calculó con el índice de costo (CI) de la empresa. Ya en crucero, para recuperar horario, te piden volar con un CI mucho más alto. ¿Qué esperas?","opciones":["Menos consumo, porque llegas antes y vuelas menos tiempo.","Ningún cambio, porque el trayecto ya quedó fijado en el OFP.","Más velocidad y más consumo que el trayecto planificado.","Más consumo, que se descuenta de la reserva final prevista."],"correcta":2,"explicacion":"Un CI alto le da más peso al costo del tiempo: el FMS vuela más rápido y gasta más combustible. Como el trayecto del OFP se calculó con otro CI, la predicción al destino baja y tienes que revisarla.","referencia":"Airbus, Getting to Grips with Fuel Economy (2004), 3 y 5.3.5","metadatos":{"tema":"C05","capitulo":5}},{"id":"ev-10","enunciado":"Vuelas para un operador de Estados Unidos en una ruta internacional con reactores (14 CFR 121.645 (b)). Además del combustible al destino, al alterno y de 30 minutos de espera a 1.500 ft, ¿qué te pide la FAA para lo imprevisto?","opciones":["Un 5 % del trayecto, y nunca menos de 5 minutos de espera sobre el destino.","Un 10 % del tiempo total de vuelo desde el origen hasta el destino.","45 minutos más a consumo normal de crucero, después del alterno.","Dos horas a consumo normal de crucero sobre el destino."],"correcta":1,"explicacion":"En vuelos internacionales con reactores la FAA no usa el 5 %: pide combustible para volar un 10 % del tiempo total hasta el destino, además del alterno y de 30 minutos de espera a 1.500 ft (121.645 (b)). El 5 % con piso de 5 minutos es la contingencia del RAC 121 y de la OACI; los 45 minutos son la reserva de la FAA doméstica (121.639), y las 2 horas, lo que pide la FAA para un destino sin alterno (121.645 (c)).","referencia":"FAA, 14 CFR 121.645 (b) y (c); 121.639; RAC 121, 121.2645 (c)(3)","metadatos":{"tema":"C06","capitulo":6}},{"id":"ev-11","enunciado":"Llegas a un punto de nueva planificación en vuelo. Desde allí, el combustible requerido hasta el destino es 6.400 kg, y 5 minutos de espera a 1.500 ft sobre el destino cuestan 230 kg. Según el RAC 121, ¿qué contingencia debes tener para continuar?","opciones":["230 kg","640 kg","550 kg","320 kg"],"correcta":3,"explicacion":"Desde un punto de nueva planificación, la contingencia es el 5 % del combustible requerido desde ese punto (320 kg), con el piso de 5 minutos (230 kg); se toma el mayor. En vuelos largos suele mandar el 5 %.","referencia":"RAC 121, 121.2645 (c)(3) y (d)","metadatos":{"tema":"C06","capitulo":6}},{"id":"ev-12","enunciado":"Vuelo nacional a un destino con buen tiempo pronosticado, dos pistas separadas y aproximación por instrumentos. Tu primer oficial propone despachar sin alterno y llevar 15 minutos de espera, «como permite la OACI». Según el RAC 121, ¿qué respondes?","opciones":["No: en Colombia todo vuelo debe tener al menos un aeródromo alterno.","Sí: el RAC 121 adopta los valores del Anexo 6, incluido este.","Sí, llevando 2 horas de combustible a consumo normal de crucero sobre el destino.","Sí, si el despachador lo aprueba y lo registra en el despacho."],"correcta":0,"explicacion":"El RAC 121 dice que en Colombia no se considera el aeródromo aislado y que todos los vuelos deben contar, por lo menos, con un aeródromo alterno; los apartados de vuelo sin alterno están reservados. Los 15 minutos de espera y las 2 horas sobre el destino son valores de la OACI y de la FAA que el RAC 121 no adopta.","referencia":"RAC 121, 121.001 (aeródromo aislado, Nota); 121.2645 (c)(4)(iii) y (iv)","metadatos":{"tema":"C07","capitulo":7}},{"id":"ev-13","enunciado":"A mitad de ruta, el TAF de tu alterno se enmienda con niebla bajo mínimos a tu hora prevista. Tu predicción al destino queda 350 kg por encima del alterno más la reserva final. Con el despachador eligen otro alterno al alcance del avión, que pide 250 kg más que el original. ¿Qué es correcto?","opciones":["Mantener el alterno original, porque el despacho no se puede cambiar en vuelo.","Pedir demoras al ATC: con el nuevo alterno ya quedas por debajo del alterno más la reserva final.","Enmendar y registrar el despacho: quedas unos 100 kg sobre alterno más reserva final.","Declarar combustible mínimo, porque el nuevo alterno te deja con menos margen del planificado."],"correcta":2,"explicacion":"El RAC 121 permite enmendar el despacho en ruta para incluir cualquier alterno dentro del alcance del avión, y quien lo enmienda lo registra. Recalculado, quedas unos 100 kg sobre alterno más reserva final (350 − 250), no por debajo: es poco margen y hay que vigilar la llegada, pero no es combustible mínimo, que exige estar obligado a un aeródromo.","referencia":"RAC 121, 121.2625 (b)(2) e (i); 121.2553 (b)(1) y (b)(2)","metadatos":{"tema":"C07","capitulo":7}},{"id":"ev-14","enunciado":"En el briefing de llegada tu comandante dice: «Tenemos 1.300 kg de reserva final; si hace falta, son 30 minutos más de espera». ¿Qué le respondes?","opciones":["Correcto, siempre que declaremos combustible mínimo antes de empezar a usarla.","No: es lo mínimo con lo que debemos aterrizar, no tiempo para esperar.","Correcto, pero solo después de renunciar al alterno de destino.","No: la reserva final son 45 minutos, porque se mide a consumo normal de crucero."],"correcta":1,"explicacion":"La reserva final es la cantidad mínima con la que se aterriza en cualquier aeródromo y no se planifica para consumirse. Si calculas que aterrizarás por debajo de ella aun en el aeródromo más cercano donde puedes aterrizar con seguridad, ya es una emergencia: «MAYDAY, MAYDAY, MAYDAY, COMBUSTIBLE».","referencia":"RAC 121, 121.2645 (c)(5)(ii); 121.2553 (b)(3) y Nota 1","metadatos":{"tema":"C08","capitulo":8}},{"id":"ev-15","enunciado":"Ya estás obligado a aterrizar en tu destino. FOB 2.150 kg, reserva final prevista 1.400 kg, aproximación y aterrizaje unos 300 kg, espera 50 kg/min. ¿Cuántos minutos puedes esperar sin aterrizar por debajo de la reserva final?","opciones":["Unos 15 minutos","Unos 37 minutos","Unos 3 minutos","Unos 9 minutos"],"correcta":3,"explicacion":"Quedan 2.150 menos 300 menos 1.400 = 450 kg por encima de la reserva, y 450 ÷ 50 = 9 minutos. Con 15 olvidas descontar la aproximación y con 37 tratas la reserva final como si fuera combustible disponible.","referencia":"RAC 121, 121.2553 (b); 121.2645 (c)(5)(ii)","metadatos":{"tema":"C08","capitulo":8}},{"id":"ev-16","enunciado":"En una entrevista con un operador de Estados Unidos te preguntan por la FAA en vuelos domésticos (14 CFR 121.639): después de volar al destino y al alterno más lejano, ¿qué reserva se exige?","opciones":["45 minutos a consumo normal de crucero.","30 minutos a velocidad de espera a 1.500 ft.","10 % del tiempo de vuelo más 30 minutos de espera.","2 horas a consumo normal de crucero."],"correcta":0,"explicacion":"La FAA doméstica pide 45 minutos a consumo normal de crucero después del alterno, sin una línea de contingencia aparte. Los 30 minutos de espera a 1.500 ft son la reserva del RAC 121, de la OACI y de la FAA internacional con reactores, que además suma el 10 % del tiempo (121.645).","referencia":"FAA, 14 CFR 121.639 (c); 121.645 (b) y (c)","metadatos":{"tema":"C08","capitulo":8}},{"id":"ev-17","enunciado":"Ruta larga sobre selva. Ante una despresurización en el punto más crítico necesitarías 4.100 kg para descender, llegar al alterno en ruta, esperar 15 minutos a 1.500 ft y aterrizar. Con trayecto, contingencia, alterno y reserva final llegarías a ese punto con 3.750 kg. Según el RAC 121, ¿cuánto adicional lleva el OFP?","opciones":["Nada, porque esa falla es muy poco probable.","4.100 kg, todo el escenario de la falla.","350 kg, lo que falta para cubrir el escenario.","7.850 kg, la suma del plan y del escenario."],"correcta":2,"explicacion":"El adicional es solo la cantidad suplementaria que falta cuando los demás componentes no alcanzan para ese escenario: 4.100 menos 3.750 = 350 kg. La norma advierte que, aun así, una falla justo en ese punto puede terminar en una emergencia de combustible.","referencia":"RAC 121, 121.2645 (c)(6)(i) y Nota 1; OACI, Doc 9976, 4.24.2","metadatos":{"tema":"C09","capitulo":9}},{"id":"ev-18","enunciado":"El TAF de destino trae TEMPO de tormentas a tu hora de llegada y la empresa sabe que hay esperas de hasta 18 minutos. El despacho propone 300 kg de extra y la espera cuesta 42 kg/min. Eres el PIC. ¿Qué haces según el RAC 121?","opciones":["Aceptas 300 kg, porque el extra lo fija la política de la empresa.","Subes el extra a unos 760 kg: la cantidad la decides tú como PIC.","Dejas el extra en 300 kg y cubres el resto de la espera con la contingencia.","Pides al despacho un adicional por la meteorología del destino."],"correcta":1,"explicacion":"Una espera previsible no se carga a la contingencia: va en el plan o como extra, y aquí el despacho la trata como extra. En el RAC 121 esa cantidad es la que a juicio del PIC puede añadirse: 18 × 42 ≈ 760 kg. El adicional solo cubre la falla en el punto crítico, EDTO u otros requisitos.","referencia":"RAC 121, 121.2645 (b)(2)(iv), (c)(3), Nota, (c)(6) y (c)(7)","metadatos":{"tema":"C09","capitulo":9}},{"id":"ev-19","enunciado":"Preparas un vuelo con buen tiempo en destino y alterno, sin NOTAM relevantes ni congestión conocida. Tu compañero propone llenar tanques «por si acaso». ¿Qué criterio aplicas para el discrecional?","opciones":["Llenar tanques, porque más combustible siempre es un vuelo más seguro.","Cargar siempre el mínimo legal, porque el costo es lo único que manda.","Cargar hasta la masa máxima de aterrizaje en destino.","Cargar lo que la situación justifica: el peso extra también cuesta."],"correcta":3,"explicacion":"El discrecional se decide con meteorología, NOTAM, tránsito, experiencia y demoras posibles, y aquí nada justifica llenar tanques. El peso extra aumenta el consumo y el costo: lo correcto es lo que la situación justifica y lo que puedes explicar.","referencia":"RAC 121, 121.2645 (c)(7); Boeing (Anderson), Fuel Conservation Operational Procedures, 2006","metadatos":{"tema":"C10","capitulo":10}},{"id":"ev-20","enunciado":"Según Airbus, si el tiempo de vuelo no cambia, el tankering conviene cuando el precio en destino dividido por el de origen es mayor que K. Con K = 1,25, combustible a 0,80 USD/kg en origen y a 0,92 USD/kg en destino, ¿conviene?","opciones":["No: la relación de precios es 1,15, menor que K.","Sí: el combustible en destino es un 15 % más caro.","Sí: basta con que K sea mayor que 1 para ahorrar.","No: solo conviene en vuelos de más de 2 horas."],"correcta":0,"explicacion":"La relación es 0,92 ÷ 0,80 = 1,15, menor que K = 1,25: el combustible que se quema por transportar combustible cuesta más que el ahorro de precio. Que el destino sea más caro no basta.","referencia":"Airbus, Getting to Grips with Fuel Economy (2004), 4.5","metadatos":{"tema":"C11","capitulo":11}},{"id":"ev-21","enunciado":"Pusieron en marcha con 9.200 kg y un rodaje largo consumió 400 kg. En crucero el FOB marca 5.920 kg y el FU acumulado desde la puesta en marcha es 2.880 kg. Tu compañero suma 8.800 kg, lo compara con el combustible de despegue y dice que cuadra. ¿Qué le respondes?","opciones":["Que cuadra: si la suma iguala el combustible de despegue, no falta nada y no hay ninguna fuga.","Que no cuadra: faltan 400 kg frente a los 9.200 kg de la puesta en marcha; posible fuga.","Que cuadra con un margen de 400 kg, que es la tolerancia normal de los indicadores.","Que no se puede saber: la prueba FOB + FU solo es válida en tierra, antes del despegue."],"correcta":1,"explicacion":"El FU incluye el rodaje, así que FOB + FU debe igualar el combustible al poner en marcha: 8.800 kg frente a 9.200 kg dejan 400 kg que ningún motor quemó. Comparar con el combustible de despegue esconde justo esa diferencia; se trata como posible fuga con el QRH de tu avión.","referencia":"Airbus, Safety First, «Fuel Leak Management in Flight» (2025), Check 1; Doc 9976, 6.6 f) y g)","metadatos":{"tema":"C12","capitulo":12}},{"id":"ev-22","enunciado":"El OFP prevé aterrizar con 3.400 kg y tu alterno más la reserva final suman 2.900 kg. Tus fuel checks, cada 40 minutos, dan −50, −130 y −210 kg frente al plan, y la suma FOB + FU cuadra. Faltan 60 minutos de vuelo. Si la tendencia sigue, ¿con cuánto aterrizas?","opciones":["Unos 3.190 kg: la diferencia que llevas hoy es la misma que tendrás al aterrizar.","Unos 2.880 kg: ya estás por debajo del alterno más la reserva final y debes pedir demoras al ATC.","Unos 3.400 kg: sin fuga, las diferencias con el OFP no cambian la predicción.","Unos 3.070 kg: sobre el alterno más la reserva final, pero con solo unos 170 kg de margen."],"correcta":3,"explicacion":"La diferencia crece 80 kg cada 40 minutos, unos 120 kg/h; en los 60 minutos que faltan se suman unos 120 kg y llegarías 330 kg bajo el plan, con unos 3.070 kg. Sigues sobre 2.900 kg, pero con poco margen: es el momento de revisar la llegada, pedir nivel o directo y preparar la cifra de desvío.","referencia":"Módulo C13, «Cómo se detecta una tendencia»; RAC 121, 121.2553 (b)(1); Doc 9976, 6.6 k)","metadatos":{"tema":"C13","capitulo":13}},{"id":"ev-23","enunciado":"Dos vuelos anotan sus diferencias frente al OFP en tres fuel checks seguidos, cada 30 minutos. Vuelo X: −150, −160 y −150 kg. Vuelo Y: −40, −110 y −180 kg. En ambos la suma FOB + FU cuadra. ¿Qué lectura es correcta?","opciones":["X es el caso más grave, porque su diferencia es mayor en todos los puntos.","Y muestra una tendencia de unos 140 kg/h que hay que proyectar; X, un desfase estable.","Ninguno muestra una tendencia: mientras la suma cuadre, las diferencias son ruido.","Los dos muestran la misma tendencia, porque terminan con diferencias parecidas."],"correcta":1,"explicacion":"Una diferencia aislada o estable puede ser ruido o un desfase fijo; varias diferencias que crecen son una tendencia. En Y la diferencia aumenta 140 kg en 60 minutos y hay que proyectarla al tiempo que queda; X va 150 kg bajo el plan, pero sin empeorar.","referencia":"Módulo C13, «Cómo se detecta una tendencia»; Doc 9976, 6.6 a), f) y g)","metadatos":{"tema":"C13","capitulo":13}},{"id":"ev-24","enunciado":"El FMS predice 3.100 kg al aterrizar. El ATC anuncia una espera de 10 minutos (consumes 45 kg/min) y vectores que alargan la llegada unos 150 kg; aún no los cargas. Tu alterno más la reserva final suman 2.600 kg. ¿Qué predicción vale y qué haces?","opciones":["3.100 kg: continúas, porque el FMS todavía no muestra ningún cambio.","Unos 2.650 kg: solo cuenta la espera y quedas sobre alterno más reserva final.","Unos 2.500 kg: bajo alterno más reserva final; pides información de demoras al ATC.","Unos 2.500 kg: bajo alterno más reserva final; declaras «combustible mínimo»."],"correcta":2,"explicacion":"Cargados la espera (450 kg) y los vectores (150 kg), la predicción baja a unos 2.500 kg, bajo alterno más reserva final: la norma pide información de demoras. Todavía no es combustible mínimo, porque aún puedes desviarte; ese aviso exige estar obligado a un aeródromo.","referencia":"RAC 121, 121.2553 (b)(1) y (b)(2); Anexo 6, Parte I, 4.3.7.2.1","metadatos":{"tema":"C14","capitulo":14}},{"id":"ev-25","enunciado":"Después del despegue, los flaps quedan trabados extendidos y el procedimiento de tu avión permite seguir en esa configuración. ¿Cómo sabes si todavía llegas al destino con alterno y reserva final?","opciones":["Con la predicción del FMS, que corrige sola cualquier configuración anormal.","Con el OFP original, porque la contingencia cubre el consumo adicional de una falla.","Recalculando con las tablas o el procedimiento del fabricante para esa configuración.","Con el fuel check del próximo punto del MO; hasta entonces no hay nada que recalcular."],"correcta":2,"explicacion":"Una falla que aumenta el consumo (tren abajo, flaps trabados, motor inoperativo) cambia todo el cálculo, y usar el combustible para algo no previsto exige un nuevo análisis. El OFP no contempla esa penalización: se recalcula con las tablas o el procedimiento del fabricante.","referencia":"Módulo C15, «Anormales»; RAC 91, 91.610 (b); Anexo 6, Parte I, 4.3.6.7","metadatos":{"tema":"C15","capitulo":15}},{"id":"ev-26","enunciado":"Antes de entrar en espera, tu predicción al destino queda 600 kg por encima del alterno más la reserva final. El ATC te da una hora prevista de aproximación dentro de 8 minutos; consumes 50 kg/min y el alterno sigue bien. ¿Qué decisión tiene sentido?","opciones":["Esperar: tiene final conocido y tu margen la cubre, con unos 200 kg sobre alterno más reserva.","Desviarte ya: cualquier espera sobre el destino pone en riesgo el alterno más la reserva final.","Declarar combustible mínimo al entrar, para que el ATC no te alargue la espera asignada.","Pedir prioridad al ATC, porque la espera consumirá parte del margen que tienes hoy."],"correcta":0,"explicacion":"Esperar tiene sentido cuando la espera tiene un final conocido y el combustible lo cubre: 8 minutos cuestan 400 kg y quedan unos 200 kg sobre alterno más reserva final. Combustible mínimo exige estar obligado a un aeródromo, y no es tu caso.","referencia":"Módulo C15, tabla «Las decisiones y su efecto»; RAC 121, 121.2553 (b)(1) y (b)(2)","metadatos":{"tema":"C15","capitulo":15}},{"id":"ev-27","enunciado":"Estás en espera sobre el destino. Aún puedes salir al alterno y aterrizar allí con la reserva final intacta, y la predicción al destino conserva el alterno más la reserva final. Tu compañero quiere declarar «combustible mínimo» por si acaso. ¿Qué le dices?","opciones":["Que sí: conviene declararlo antes de que la espera se alargue, así el ATC te da prioridad.","Que no: aún pueden desviarse; si la predicción baja de alterno más reserva final, piden demoras.","Que sí: basta con que la contingencia se esté consumiendo en la espera para poder declararlo.","Que no: el combustible mínimo solo se declara cuando el FOB indicado ya llegó a la reserva final."],"correcta":1,"explicacion":"El combustible mínimo exige estar obligado a un aeródromo específico; mientras puedas desviarte con la reserva final intacta, el Doc 9976 lo considera inapropiado. El paso que sigue, si la predicción cae bajo el alterno más la reserva final, es pedir información de demoras.","referencia":"RAC 121, 121.2553 (b)(1) y (b)(2); Doc 9976, 6.10.2 y escenario 1 (explicación)","metadatos":{"tema":"C16","capitulo":16}},{"id":"ev-28","enunciado":"Declaraste «COMBUSTIBLE MÍNIMO» y el ATC responde: «RECIBIDO, PREVEA DEMORA DE 10 MINUTOS». Eres el número 4 de la secuencia. ¿Qué es correcto?","opciones":["Es un error del ATC: después de «combustible mínimo» debe darte prioridad y aproximación directa.","Es correcto, pero debes repetir «combustible mínimo» en cada frecuencia para conservar la prioridad.","Es un error del ATC: debe pedirte personas a bordo y autonomía, como en toda emergencia.","Es correcto: el aviso no da prioridad; si tu cálculo cae bajo la reserva final, declaras MAYDAY."],"correcta":3,"explicacion":"«Combustible mínimo» no es una emergencia ni da prioridad: el ATC te informa la demora prevista y avisa a la siguiente dependencia al transferirte. Si tu cálculo al aeródromo más cercano cae bajo la reserva final, declaras MAYDAY, que sí da prioridad (211.360 (a)).","referencia":"Doc 4444, 12.3.1.3, 15.5.4.1 y 10.2.5; Doc 9976, 6.8.5, Nota 1; RAC 211, 211.360 (a); RAC 121, 121.2553 (b)(3)","metadatos":{"tema":"C16","capitulo":16}},{"id":"ev-29","enunciado":"Vas en crucero, a 45 minutos del destino. Cerró tu único alterno alcanzable, así que quedaste obligado al destino, y calculas que cualquier demora en la llegada te haría aterrizar bajo la reserva final. ¿Cuándo declaras «combustible mínimo»?","opciones":["Ahora, al controlador que tienes, para que la dependencia que organiza tu llegada lo sepa a tiempo.","Al contactar la aproximación, porque el centro de control no maneja la secuencia de llegada.","Solo cuando el ATC te asigne una espera, porque antes no hay ningún cambio de autorización.","Cuando el FOB indicado llegue a la cantidad de reserva final prevista que trae el OFP."],"correcta":0,"explicacion":"Se declara tan pronto se cumplen las dos condiciones; hacerlo tarde le quita al ATC el tiempo para planear tu llegada. El controlador te informa las demoras previstas y lo transmite a la dependencia que te recibe.","referencia":"RAC 121, 121.2553 (b)(2); Doc 4444, 10.2.5 y 15.5.4.1","metadatos":{"tema":"C16","capitulo":16}},{"id":"ev-30","enunciado":"Estás obligado al destino y ya declaraste combustible mínimo con 2.100 kg a bordo; tu reserva final prevista es 1.500 kg. Cierran la pista sin hora de reapertura. El aeródromo más cercano con aterrizaje seguro está a 12 minutos (55 kg/min) y la aproximación cuesta unos 150 kg. ¿Qué haces?","opciones":["Repites «combustible mínimo»: todavía tienes a bordo más que la reserva final.","Pides información de demoras sobre la reapertura antes de declarar cualquier otra cosa.","Declaras MAYDAY solo cuando el FOB indicado llegue a 1.500 kg durante el desvío.","Declaras «MAYDAY, MAYDAY, MAYDAY, COMBUSTIBLE»: aterrizarías con unos 1.290 kg."],"correcta":3,"explicacion":"12 minutos a 55 kg/min son 660 kg, más 150 kg de aproximación: aterrizarías con unos 1.290 kg, menos que la reserva final prevista de 1.500 kg. El criterio es el cálculo al aterrizar en el aeródromo más cercano, no el FOB de este momento, así que se declara ya.","referencia":"RAC 121, 121.2553 (b)(3); Anexo 6, Parte I, 4.3.7.2.3; Doc 9976, 6.9","metadatos":{"tema":"C17","capitulo":17}},{"id":"ev-31","enunciado":"Según la NTSB (AAR-91/04), ¿cuál fue la causa probable del accidente del vuelo Avianca 052 en 1990?","opciones":["No manejar adecuadamente el combustible ni comunicar al ATC una emergencia de combustible antes de agotarlo.","Una falla del sistema de indicación de cantidad, que mostraba más combustible del que había.","La cortante de viento en la aproximación final, que impidió aterrizar en el primer intento.","La saturación del alterno, que obligó a la tripulación a esperar más de una hora antes de desviarse."],"correcta":0,"explicacion":"La NTSB determinó que la tripulación no manejó adecuadamente el combustible ni comunicó una emergencia de combustible antes de agotarlo, y señaló como contribuyentes no usar el despacho de la aerolínea y la falta de terminología normalizada. La cortante de viento, la fatiga y el estrés contribuyeron a que no se completara el primer intento, pero no son la causa probable.","referencia":"NTSB, AAR-91/04, 3.2 (causa probable) y 4 (recomendación A-91-33)","metadatos":{"tema":"C17","capitulo":17}},{"id":"ev-32","enunciado":"El informe final de la Aerocivil sobre el vuelo LaMia 2933 (2016) señaló factores de la tripulación. ¿Cuál corresponde a ese informe?","opciones":["Declaró MAYDAY demasiado pronto y saturó la frecuencia de aproximación de Rionegro.","Se fijó en continuar con combustible muy limitado y pidió prioridad y emergencia tarde.","Aplicó de memoria el procedimiento de desbalance y alimentó una fuga de combustible.","Usó un factor de conversión en libras como si fuera en kilos al calcular la carga."],"correcta":1,"explicacion":"El informe señala la pérdida de conciencia situacional y la fijación de la tripulación en continuar con combustible extremadamente limitado, y la solicitud tardía de prioridad y de emergencia. El desbalance aplicado de memoria es el caso Air Transat 236, y el error de libras y kilos, Air Canada 143.","referencia":"Aerocivil, informe final COL-16-37-GIA, 3.2 (causas probables) y 3.3 (factores contribuyentes)","metadatos":{"tema":"C17","capitulo":17}},{"id":"ev-33","enunciado":"Entras en espera con 4.100 kg. Para abandonarla hacia el alterno necesitas 3.200 kg (1.700 hasta el alterno más 1.500 de reserva final). Consumes 60 kg/min y el ATC anuncia 35 minutos de demora por una pista cerrada, sin hora de reapertura. ¿Qué haces?","opciones":["Aceptas la espera completa: todavía tienes a bordo mucho más que la reserva final.","Aceptas y declaras «combustible mínimo» al entrar, para que el ATC acorte la demora.","Calculas unos 15 minutos disponibles: fijas la hora de salida al alterno y se lo dices al ATC.","Esperas los 35 minutos y, si no hay aproximación, declaras MAYDAY para aterrizar primero."],"correcta":2,"explicacion":"(4.100 − 3.200) ÷ 60 = 15 minutos, menos que los 35 anunciados, y la causa (pista cerrada sin hora) no da certeza. Si no hay aproximación, sales hacia el alterno a los 15 minutos; aceptar la espera completa es renunciar al alterno.","referencia":"Módulo C18, «Tiempo disponible en espera»; RAC 121, 121.2553 (b)(1)","metadatos":{"tema":"C18","capitulo":18}},{"id":"ev-34","enunciado":"Tu MO permite comprometerte con el destino y se cumplen sus condiciones: buen tiempo y hora prevista de aproximación asignada. En la espera tienes 2.600 kg; la aproximación y el aterrizaje cuestan 200 kg y la reserva final prevista es 1.400 kg. Consumes 50 kg/min. ¿Cuánto puedes esperar como máximo?","opciones":["Unos 20 minutos: para abandonar la espera cuentan la aproximación y la reserva final.","Unos 24 minutos: al comprometerte con el destino, solo hay que restar la reserva final.","Unos 52 minutos: comprometido, ya no hay alterno que conservar ni nada que restar.","Ninguno: una vez comprometido con el destino, ya no se puede aceptar ninguna espera."],"correcta":0,"explicacion":"Comprometido con el destino, el combustible para abandonar la espera es la aproximación y el aterrizaje más la reserva final: (2.600 − 200 − 1.400) ÷ 50 = 20 minutos. Desde ese momento, además, aplica el combustible mínimo si cualquier cambio te deja bajo la reserva final.","referencia":"Módulo C18, «La cifra que manda en una espera»; Doc 9976, 6.4.27 y 6.4.28; RAC 121, 121.2553 (b)(2)","metadatos":{"tema":"C18","capitulo":18}},{"id":"ev-35","enunciado":"Hay tormenta sobre el destino. Tu alterno está a 30 minutos con buen tiempo y en la frecuencia varios aviones piden desviarse allí. Tu combustible todavía cubre 12 minutos de espera conservando el alterno. ¿Qué es lo más sensato?","opciones":["Esperar los 12 minutos: el combustible del alterno se calculó para cualquier situación allá.","Esperar y declarar combustible mínimo, para asegurar tu turno de aproximación en el destino.","Pedir al ATC prioridad para llegar al alterno antes que los demás, sin declarar nada.","Desviarte ahora y preguntar por el estado del alterno: allá también puede haber espera."],"correcta":3,"explicacion":"El combustible para el alterno se calculó para un aeropuerto sin congestión, y si varios desvíos van allá también habrá espera; desviarte temprano te pone al comienzo de la fila. En los desvíos a Valencia de 2012, cuatro de doce vuelos declararon MAYDAY por combustible (CIAIAC).","referencia":"Doc 9976, 6.4.25; CIAIAC, informe IN-010/2010, 1.9","metadatos":{"tema":"C19","capitulo":19}},{"id":"ev-36","enunciado":"Hay tormenta sobre el destino. El ATC no da hora prevista de aproximación ni demora máxima, y el pronóstico para la próxima hora es incierto. Tu MO permite «desviarse o comprometerse» con las condiciones del Doc 9976. ¿Puedes usar el combustible del alterno para seguir esperando?","opciones":["Sí: el MO lo permite y basta con que el alterno siga con buen tiempo si luego lo necesitas.","Sí: mientras la predicción al destino quede sobre la reserva final, cualquier espera es aceptable.","No: faltan el aterrizaje asegurado, la hora prevista de aproximación y la demora máxima confirmada.","No: el combustible del alterno solo puede usarse después de haber declarado combustible mínimo al ATC."],"correcta":2,"explicacion":"Las condiciones típicas para comprometerse son un aterrizaje asegurado en las condiciones actuales y previstas (incluida una falla probable de un equipo), una hora prevista de aproximación asignada o la demora máxima confirmada por el ATC. Sin ninguna de ellas, gastar el combustible del alterno es quedarte con una sola opción incierta.","referencia":"Doc 9976, 6.4.27 y 6.4.28 a) y b)","metadatos":{"tema":"C19","capitulo":19}},{"id":"ev-37","enunciado":"Llegas al punto de nueva planificación de un vuelo largo con 7.900 kg. Desde allí al destino final necesitas: trayecto 5.600, contingencias 280, alterno 900 y reserva final 1.300 kg; adicional 0. El destino intermedio está a 25 minutos. ¿Qué haces?","opciones":["Sigues al destino final: la contingencia está hecha para consumirse en ruta.","Sigues y, si hace falta, declaras combustible mínimo al llegar al destino final.","Sigues, porque tienes más que el trayecto más la reserva final (6.900 kg).","Vas al destino intermedio: te faltan unos 180 kg para el combustible requerido."],"correcta":3,"explicacion":"Para continuar desde el punto de nueva planificación hacen falta trayecto desde ese punto, contingencias, alterno, reserva final y adicional si aplica: 8.080 kg, y tienes 7.900. La decisión estaba preparada: aterrizas en el intermedio, cargas combustible y el despachador reprograma.","referencia":"RAC 121, 121.2645 (c)(3) y (d); 121.2625 (a) y (b)","metadatos":{"tema":"C20","capitulo":20}},{"id":"ev-38","enunciado":"En un vuelo sin punto de redespacho, una rerruta por tormentas te hizo volar 30 minutos más de lo previsto. La predicción todavía conserva el alterno más la reserva final. ¿Qué exige la norma?","opciones":["Nada, mientras la predicción conserve el alterno más la reserva final.","Un nuevo análisis y, si corresponde, ajustar la operación prevista.","Declarar combustible mínimo, porque usaste combustible no planificado.","Volver al origen, porque ya no se cumple el OFP con el que te despacharon."],"correcta":1,"explicacion":"El uso del combustible después del inicio del vuelo para fines distintos de los previstos exige un nuevo análisis y, si corresponde, un ajuste de la operación. Conservar el alterno más la reserva final no te exime de replanificar desde donde estás; una rerruta larga es justo el motivo.","referencia":"RAC 91, 91.610 (b); Anexo 6, Parte I, 4.3.6.7; RAC 121, 121.2553 (b), Nota","metadatos":{"tema":"C20","capitulo":20}},{"id":"ev-39","enunciado":"Tu contingencia es de 300 kg. En el mismo vuelo te dejan 15 minutos a un nivel más bajo (+80 kg), usas antihielo 10 minutos en el descenso (+40 kg), te dan vectores (+70 kg) y una espera de 3 minutos a 45 kg/min. ¿Cuánto suman frente a la contingencia y qué correspondía hacer?","opciones":["Unos 325 kg, más que toda la contingencia: tras cada evento tocaba un fuel check y actualizar la predicción.","Solo cuenta la espera, unos 135 kg: el nivel, el antihielo y los vectores ya estaban dentro del trayecto planificado.","Nada: las demoras que impone el ATC no cuentan frente a la contingencia; se cubren con el combustible para el alterno.","Menos de la mitad de la contingencia: los factores de menos de 100 kg no alcanzan a cambiar la predicción."],"correcta":0,"explicacion":"Sumados, los cuatro factores cuestan unos 325 kg (80 + 40 + 70 + 135), más que toda la contingencia, aunque ninguno parezca grave. Por eso, cuando aparece cada factor, se hace un fuel check y se actualiza la predicción.","referencia":"Módulo C21, ejemplo; RAC 121, 121.2645 (c)(3), Nota; Doc 9976, 6.4.5","metadatos":{"tema":"C21","capitulo":21}},{"id":"ev-40","enunciado":"Haces sobrepaso en el destino con el techo en mínimos. Te queda algo más que lo necesario para ir al alterno con la reserva final. El último reporte no muestra mejora y no hay otra pista con mínimos más bajos. ¿Qué haces?","opciones":["Un segundo intento: el combustible del alterno incluye dos aproximaciones en destino.","Un segundo intento y, si falla, declaras combustible mínimo antes de salir al alterno.","Te desvías al alterno ahora: no hay razón para que el segundo intento salga distinto.","Esperas sobre el destino a que mejore, usando la reserva final como margen de espera."],"correcta":2,"explicacion":"El plan cubre un sobrepaso seguido de desvío; con apenas algo más que el combustible del alterno, un segundo intento saldría de ese combustible y te dejaría sin alterno. Sin una razón nueva para que el intento salga distinto, la decisión es el alterno, y cuanto antes, mejor.","referencia":"RAC 121, 121.2645 (c)(4)(i)(A); Doc 9976, 6.4.26","metadatos":{"tema":"C22","capitulo":22}}]$banco$::jsonb)
    as d(id text, enunciado text, opciones jsonb, correcta smallint, explicacion text, referencia text, metadatos jsonb)
),
cargadas as (
  insert into public.banco_preguntas as bp
    (banco, clave_externa, enunciado, opciones, correcta, explicacion, referencia, metadatos, activa, actualizada_en)
  select 'combustible_evaluacion', d.id, d.enunciado, d.opciones, d.correcta, coalesce(d.explicacion, ''), d.referencia,
         coalesce(d.metadatos, '{}'::jsonb), true, now()
  from datos d
  on conflict (banco, clave_externa) do update set
    enunciado = excluded.enunciado,
    opciones = excluded.opciones,
    correcta = excluded.correcta,
    explicacion = excluded.explicacion,
    referencia = excluded.referencia,
    metadatos = excluded.metadatos,
    activa = true,
    actualizada_en = now()
  where (bp.enunciado, bp.opciones, bp.correcta, bp.explicacion, bp.referencia, bp.metadatos, bp.activa)
    is distinct from (excluded.enunciado, excluded.opciones, excluded.correcta, excluded.explicacion,
                      excluded.referencia, excluded.metadatos, true)
  returning 1
)
update public.banco_preguntas
set activa = false, actualizada_en = now()
where banco = 'combustible_evaluacion' and activa and clave_externa not in (select id from datos);
